(function(root){
'use strict';
const printerUrl='https://www.lulu.com/create/print-books';
function readiness(count){const n=count+2,pages=n+n%2;if(pages<32){const needed=29-count;return{pages,ready:false,message:`Add ${needed} more quote${needed===1?'':'s'} to reach Lulu’s 32-page paperback minimum.`}}if(pages>800)return{pages,ready:false,message:'This edition is over Lulu’s 800-page paperback limit. Split it into two books.'};return{pages,ready:true,message:`${pages} pages · 5 × 8 in · ready to prepare for Lulu.`}}
const spineWidth=pages=>pages/444+.06;
function instructions(book,pages){return `${book.title}\nPRINT YOUR COMMONPLACE BOOK\n\n1. Unzip this folder.\n2. Visit ${printerUrl} and start a Print Book project.\n3. Choose Print Copies for Your Own Use (personal printing).\n4. Upload 01-interior.pdf as the interior/manuscript.\n5. Choose Novella 5 x 8 inches, paperback perfect bound, Standard Black & White, 60# cream paper, matte cover.\n6. Upload 02-cover.pdf as your own cover. This is a single full-wrap PDF: back + spine + front.\n7. Review Lulu's preview and exact cover template, then choose quantity, shipping address and payment on Lulu.\n\nBOOK DETAILS\nInterior: ${pages} pages; 5 x 8 inches; no full bleed.\nCover: ${(10.25+spineWidth(pages)).toFixed(5)} x 8.25 inches, including 0.125 inch outer bleed.\nSpine: ${spineWidth(pages).toFixed(5)} inches, using Lulu's paperback formula.\nFonts embedded. Interior is grayscale; cover keeps your selected colors.\n\nUpload the two PDFs, not this ZIP and not a reading PDF. Lulu handles payment, printing and shipping. No order is placed by downloading these files. Compare the cover against the exact template Lulu supplies before paying.\n\nOfficial instructions: https://help.lulu.com/en/support/solutions/articles/64000255486-how-to-create-a-print-book\nFile specifications: https://assets.lulu.com/media/guides/en/lulu-book-creation-guide.pdf\n`}
const table=Uint32Array.from({length:256},(_,i)=>{let n=i;for(let j=0;j<8;j++)n=(n&1)?0xedb88320^(n>>>1):n>>>1;return n>>>0});
function crc(bytes){let n=0xffffffff;for(const b of bytes)n=table[(n^b)&255]^(n>>>8);return(n^0xffffffff)>>>0}
function zip(files){const encoder=new TextEncoder(),local=[],central=[];let offset=0;for(const file of files){if(!/^[a-zA-Z0-9_.-]{1,100}$/.test(file.name))throw Error('Invalid print file name.');const name=encoder.encode(file.name),data=typeof file.data==='string'?encoder.encode(file.data):file.data;if(!(data instanceof Uint8Array))throw Error('Invalid print file.');const sum=crc(data),header=new Uint8Array(30+name.length),h=new DataView(header.buffer);h.setUint32(0,0x04034b50,true);h.setUint16(4,20,true);h.setUint16(6,0x800,true);h.setUint16(12,33,true);h.setUint32(14,sum,true);h.setUint32(18,data.length,true);h.setUint32(22,data.length,true);h.setUint16(26,name.length,true);header.set(name,30);local.push(header,data);const entry=new Uint8Array(46+name.length),c=new DataView(entry.buffer);c.setUint32(0,0x02014b50,true);c.setUint16(4,20,true);c.setUint16(6,20,true);c.setUint16(8,0x800,true);c.setUint16(14,33,true);c.setUint32(16,sum,true);c.setUint32(20,data.length,true);c.setUint32(24,data.length,true);c.setUint16(28,name.length,true);c.setUint32(42,offset,true);entry.set(name,46);central.push(entry);offset+=header.length+data.length}const centralSize=central.reduce((n,b)=>n+b.length,0),end=new Uint8Array(22),e=new DataView(end.buffer);e.setUint32(0,0x06054b50,true);e.setUint16(8,files.length,true);e.setUint16(10,files.length,true);e.setUint32(12,centralSize,true);e.setUint32(16,offset,true);const output=new Uint8Array(offset+centralSize+22);let pos=0;for(const b of [...local,...central,end]){output.set(b,pos);pos+=b.length}return output}
root.CommonplacePrint={readiness,spineWidth,instructions,zip,printerUrl};
})(typeof window!=='undefined'?window:globalThis);
